import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../../core/theme/app_theme.dart';import 'auth_providers.dart';class SplashScreen extends ConsumerStatefulWidget{const SplashScreen({super.key});@override ConsumerState<SplashScreen>createState()=>_SplashState();}class _SplashState extends ConsumerState<SplashScreen>with SingleTickerProviderStateMixin{late final AnimationController controller;late final Animation<double>fade;@override void initState(){super.initState();controller=AnimationController(vsync:this,duration:const Duration(milliseconds:1200))..forward();fade=CurvedAnimation(parent:controller,curve:Curves.easeOut);Future.delayed(const Duration(milliseconds:1500),()async{final has=await ref.read(authSessionProvider.notifier).hasToken();if(mounted)context.go(has?'/home':'/login');});}@override void dispose(){controller.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(backgroundColor:AppTheme.primary,body:FadeTransition(opacity:fade,child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Container(width:92,height:92,decoration:BoxDecoration(border:Border.all(color:AppTheme.gold,width:2),shape:BoxShape.circle),child:const Icon(Icons.directions_run,color:AppTheme.gold,size:42)),const SizedBox(height:22),const Text('BLACK HORSE',style:TextStyle(color:Colors.white,fontSize:25,letterSpacing:5,fontWeight:FontWeight.w300)),const SizedBox(height:8),const Text('EQUESTRIAN EXCELLENCE',style:TextStyle(color:AppTheme.gold,fontSize:10,letterSpacing:2))]))));}
